// Pega os results do HTTP Request anterior (GAQL customer_client)
const results = ($input.first().json && $input.first().json.results) || [];

// Extrai os IDs e nomes das sub-contas ativas
const accounts = results
  .map(r => r.customerClient)
  .filter(c => c && c.id)
  .map(c => ({ customerId: c.id, name: c.descriptiveName || `Conta ${c.id}` }));

// Retorna 1 item por sub-conta para o proximo node iterar
return accounts.map(a => ({ json: a }));

// Agrega metricas de todas as contas e formata texto pro WhatsApp
const allItems = $input.all();
const accounts = {};

for (const item of allItems) {
    // Se o item veio com erro (Continue On Fail), pula
    if (item.json && item.json.error) continue;
    const chunks = Array.isArray(item.json) ? item.json : [item.json];
    for (const chunk of chunks) {
          const results = (chunk && chunk.results) || [];
          for (const row of results) {
                  const id = row.customer && row.customer.id;
                  if (!id) continue;
                  if (!accounts[id]) {
                            accounts[id] = { id, name: (row.customer.descriptiveName || `Conta ${id}`), cost: 0, clicks: 0, impressions: 0, conversions: 0 };
                  }
                  accounts[id].cost += Number((row.metrics && row.metrics.costMicros) || 0) / 1000000;
                  accounts[id].clicks += Number((row.metrics && row.metrics.clicks) || 0);
                  accounts[id].impressions += Number((row.metrics && row.metrics.impressions) || 0);
                  accounts[id].conversions += Number((row.metrics && row.metrics.conversions) || 0);
          }
    }
}

const ativas = Object.values(accounts).filter(a => a.cost > 0).sort((a, b) => b.cost - a.cost);
const fmt = n => n.toLocaleString('pt-BR', { maximumFractionDigits: 2 });
const $$ = n => `R$ ${n.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
const hoje = new Date().toLocaleDateString('pt-BR');

let texto = `*Relatorio Google Ads* - ${hoje}\nPeriodo: hoje\nContas ativas: ${ativas.length}\n\n`;
if (ativas.length === 0) {
    texto += '_Nenhuma conta com gasto > 0 no periodo._';
} else {
    let tCost = 0, tClk = 0, tConv = 0;
    for (const a of ativas) {
          texto += `*${a.name}*\nGasto: ${$$(a.cost)}\nCliques: ${fmt(a.clicks)}\nConversoes: ${fmt(a.conversions)}\n`;
          if (a.conversions > 0) texto += `CPA: ${$$(a.cost / a.conversions)}\n`;
          texto += `\n`;
          tCost += a.cost; tClk += a.clicks; tConv += a.conversions;
    }
    texto += `------------\n*TOTAL*\nGasto: ${$$(tCost)}\nCliques: ${fmt(tClk)}\nConversoes: ${fmt(tConv)}\n`;
    if (tConv > 0) texto += `CPA Medio: ${$$(tCost / tConv)}`;
}

return [{ json: { mensagem: texto, totalContasAtivas: ativas.length } }];
